INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b4a145ff-c7e3-4083-bb66-921abf7f0735', 'c3c3c3c3-3030-4000-8000-000000000003', 6, 'Dia 6 — Digital', 'Semana 1: Parar', '{"pch": "O olho n\u00e3o se farta de ver\u2026 nem o ouvido de ouvir. O scroll infinito \u00e9 a torre de Babel moderna.", "verse": "Ec 1,8", "lectio": "Leia Ec 1,1-11. Vaidade das vaidades.", "practice": "Fique 2 horas sem celular. Observe o que acontece dentro de voc\u00ea.", "question": "Quanto tempo por dia sua mente \u00e9 alimentada por telas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;